{
  "name":         "socketracer",
  "description":  "A multi-player real time racing game to demonstrate the SocketStream framework",
  "version":      "0.0.1",
  "author":       "Alan Milford <alan.milford@teamaol.com>",
  "dependencies": {
    "control":  ">= 0.1.7",
    "socketstream":  ">= 0.2.5"
  },
  "engines":      { "node": "> 0.4.5" }
}

body {
  font: normal 15px 'Lucida Grande', 'Tahoma', sans-serif;
  text-align: center;
  margin: 250px 0;
}

h1 {
  font-weight: normal;
}

   var ss = require('socketstream');     // Initializes the SS global variable

   ss.load();                            // Loads the project files, including the active configuration
   console.log(ss);

   ss.start.single();                    // Start the server in single-process mode (required for Cloud9)

//   ss.redis.connect();                   // Connects to the active instance of Redis, as specified in the config file
